-- =====================================================================
-- Removed devices (v36 Fix-A, A1; owner decision 34) and the About page's
-- company details (A5). Applied live only after the owner has seen this
-- file and said "apply".
-- Rollback: supabase/rollbacks/20261113180000_removed_devices.rollback.sql
-- Tested in PGlite: supabase/tests/removed-devices-test.js
-- Generated by tools/db/gen-20261113180000-migration.js
--
-- Changes:
--   cl_removed_devices   new: the devices whose vendor row was deleted (the
--                        purge, a business deleted on seiGEN, a data fix).
--                        RLS on, no table rights for anon/authenticated.
--   trigger              every delete of a cl_vendors row adds its install
--                        to the list (reason from cl.removed_reason if set).
--   backfill             the installs in cl_activity_log 'vendor_deleted'
--                        that have no vendor row now.
--   cl_install_vendor    refuses a listed install (DEVICE_REMOVED) before
--                        anything else, so no device RPC serves it and it is
--                        never made a new vendor row (check-in, register,
--                        join, seat). Otherwise the 20261109120000 body.
--   cl_device_checkin    + p_last_vendor_id (default null): when the device
--                        says which vendor it last had and that vendor is
--                        gone, DEVICE_REMOVED and nothing is created.
--                        Otherwise the 20261025120000 body; same grants.
--                        Apps before v36 send no p_last_vendor_id and are
--                        answered as before (unless listed).
--   cl_company_info      new, anon: company name, address and website from
--                        cl_app_settings (Console → Settings) for About.
--   cl_app_settings      + 'company_website' (Console → Settings), starting
--                        with the website the About page showed.
-- A new install (no last vendor id, not listed) registers as before.
-- =====================================================================

begin;

-- 0. Preflight ----------------------------------------------------------
do $$
begin
  if to_regclass('public.cl_removed_devices') is not null or to_regproc('public.cl_company_info') is not null then
    raise exception 'removed_devices aborted: already there. Nothing was changed.';
  end if;
  if to_regprocedure('public.cl_device_checkin(text, text, text, text, text, text, text, text, uuid, text, integer)') is null
     or not exists (select 1 from pg_proc where oid = to_regprocedure('public.cl_device_checkin(text, text, text, text, text, text, text, text, uuid, text, integer)') and prosrc like '%minimum build%') then
    raise exception 'removed_devices aborted: cl_device_checkin is not the 20261025120000 version. Nothing was changed.';
  end if;
  if to_regprocedure('public.cl_install_vendor(text,text,text,boolean,text,text)') is null
     or not exists (select 1 from pg_proc where oid = to_regprocedure('public.cl_install_vendor(text,text,text,boolean,text,text)') and prosrc like '%office seats%') then
    raise exception 'removed_devices aborted: cl_install_vendor is not the 20261109120000 version. Nothing was changed.';
  end if;
end $$;

-- 1. The list -------------------------------------------------------------
create table public.cl_removed_devices (
  install_id     text primary key,
  device_key     text,
  vendor_id      uuid,          -- the deleted cl_vendors row (no foreign key: it is gone)
  business_id    uuid,
  business_name  text,
  device_code    text,
  reason         text not null,
  removed_ts     timestamptz not null default now(),
  removed_by     uuid           -- the Console staff member, when one did it
);
comment on table public.cl_removed_devices is 'Removed devices (20261113180000, decision 34): installs whose vendor row was deleted. Their check-ins and other device calls are refused (DEVICE_REMOVED) until the device is reset (a reset makes a new install).';
alter table public.cl_removed_devices enable row level security;
revoke all on table public.cl_removed_devices from public, anon, authenticated;

-- 2. Filled on every vendor delete ---------------------------------------------
create function public.cl_vendor_removed_device() returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  if nullif(btrim(coalesce(old.install_id, '')), '') is null then return old; end if;
  insert into cl_removed_devices (install_id, device_key, vendor_id, business_id, business_name, device_code, reason, removed_by)
  values (old.install_id, old.device_key, old.id, old.business_id, old.business_name, old.device_code,
          coalesce(nullif(current_setting('cl.removed_reason', true), ''), 'vendor row deleted'), cl_acting_staff())
  on conflict (install_id) do update set device_key = excluded.device_key, vendor_id = excluded.vendor_id, business_id = excluded.business_id,
    business_name = excluded.business_name, device_code = excluded.device_code, reason = excluded.reason, removed_ts = now(), removed_by = excluded.removed_by;
  return old;
end $fn$;
create trigger cl_vendors_removed_device after delete on public.cl_vendors
  for each row execute function public.cl_vendor_removed_device();

-- 3. Devices whose vendor row was deleted before this list existed ------------
insert into public.cl_removed_devices (install_id, vendor_id, business_id, business_name, reason, removed_ts)
select distinct on (a.detail->>'install_id') a.detail->>'install_id', a.target_id, nullif(a.detail->>'business_id', '')::uuid, a.detail->>'business_name',
       'vendor row deleted (from the activity log)', a.created_at
  from public.cl_activity_log a
 where a.action = 'vendor_deleted' and nullif(btrim(coalesce(a.detail->>'install_id', '')), '') is not null
   and not exists (select 1 from public.cl_vendors v where v.install_id = a.detail->>'install_id')
 order by a.detail->>'install_id', a.created_at desc;

-- 4. Every device call: a listed install is refused (20261109120000 body + marked lines)
create or replace function public.cl_install_vendor(
  p_install_id text, p_phrase text, p_device_key text, p_create boolean,
  p_business_name text default null, p_device_code text default null)
returns public.cl_vendors
language plpgsql security definer set search_path = public as $fn$
declare v cl_vendors%rowtype;
        st cl_terminals%rowtype; v_tok text; v_staff uuid;                -- office seats
begin
  perform set_config('cl.seat_terminal', '', true);                     -- office seats: who the caller is, for cl_seat_need
  perform set_config('cl.seat_staff', '', true);                        -- office seats
  if p_install_id is null or length(trim(p_install_id)) = 0 then raise exception 'install_id is required'; end if;
  if cl_norm_phrase(p_phrase) = '' then raise exception 'shop_secret_phrase is required'; end if;
  -- removed devices (v36 A1, decision 34): a device whose business was deleted gets nothing, and is never made a new vendor
  if exists (select 1 from cl_removed_devices r where r.install_id = p_install_id) then   -- removed devices
    raise exception 'DEVICE_REMOVED: This device belongs to a business that no longer exists on seiGEN. Reset this device.' using errcode = 'P0001';   -- removed devices
  end if;                                                                                -- removed devices

  select * into v from cl_vendors where install_id = p_install_id for update;
  if not found then
    if not p_create then raise exception 'This device is not registered yet' using errcode = 'P0002'; end if;
    insert into cl_vendors (business_name, install_id, device_code, shop_secret_phrase, device_key,
                            status, app_registered_at, last_checkin_at)
    values (coalesce(nullif(trim(coalesce(p_business_name,'')), ''), 'Unnamed vendor'), p_install_id,
            nullif(trim(coalesce(p_device_code,'')), ''), p_phrase, nullif(p_device_key, ''),
            'onboarding', now(), now())
    returning * into v;
    return v;
  end if;

  -- office seats: a seat sends its own phrase, then "|" and the signed-in person's token
  select * into st from cl_terminals where vendor_id = v.id and device_kind = 'seat';
  if st.id is not null then
    v_tok := nullif(split_part(coalesce(p_phrase, ''), '|', 2), '');
    p_phrase := split_part(coalesce(p_phrase, ''), '|', 1);
  end if;
  if v.shop_secret_phrase is not null and cl_norm_phrase(v.shop_secret_phrase) <> cl_norm_phrase(p_phrase) then
    raise exception 'Shop secret phrase does not match this install';
  end if;
  if v.device_key is not null and v.device_key is distinct from nullif(p_device_key, '') then
    raise exception 'This install ID is already registered to another device';
  end if;
  if v.device_key is null and nullif(p_device_key, '') is not null then
    update cl_vendors set device_key = p_device_key where id = v.id returning * into v;
  end if;
  -- office seats: an unapproved seat gets nothing (cl_seat_status / cl_seat_set_pin excepted)
  if st.id is not null then
    if st.approval_status <> 'approved' and coalesce(current_setting('cl.allow_pending_seat', true), '') <> '1' then
      raise exception 'SEAT_NOT_APPROVED: This Office seat is waiting for approval by the Owner or an Admin.' using errcode = 'P0001';
    end if;
    perform set_config('cl.seat_terminal', st.id::text, true);
    if v_tok is not null then
      select x.staff_id into v_staff from cl_shop_session(v_tok, st.id) x limit 1;
      if v_staff is not null then perform set_config('cl.seat_staff', v_staff::text, true); end if;
    end if;
  end if;
  return v;
end $fn$;

-- 5. Check-in: the vendor this device last had (20261025120000 body + marked lines)
drop function public.cl_device_checkin(text, text, text, text, text, text, text, text, uuid, text, integer);
create function public.cl_device_checkin(
  p_install_id text, p_shop_secret_phrase text, p_device_code text, p_business_name text,
  p_owner_name text default null, p_phone text default null, p_city text default null,
  p_location text default null, p_rpn_hint_id uuid default null, p_device_key text default null,
  p_app_build integer default null,                                  -- build guard
  p_last_vendor_id uuid default null)                                -- removed devices: the vendor id this device last had
returns json
language plpgsql security definer set search_path to 'public' as $function$
declare
  v_vendor cl_vendors%rowtype;
  v_messages json;
  v_terminal_id uuid;
  v_terminal_active boolean;                                         -- Phase 2
  v_branch_id uuid;                                                  -- shared stock lock
  v_app_build integer;                                               -- shared stock lock
  v_shared_lock boolean := false;                                    -- shared stock lock
  v_admin_seed json;                                                 -- admin passcode seed
  v_min_build integer := coalesce((select r.min_build from cl_app_build_rule r where r.id), 0);   -- minimum build
  v_business_name text := nullif(trim(coalesce(p_business_name,'')), '');
  v_owner_name    text := nullif(trim(coalesce(p_owner_name,'')), '');
  v_phone         text := nullif(trim(coalesce(p_phone,'')), '');
  v_city          text := nullif(trim(coalesce(p_city,'')), '');
  v_location      text := nullif(trim(coalesce(p_location,'')), '');
  v_device_code   text := nullif(trim(coalesce(p_device_code,'')), '');
begin
  -- was: inline install/phrase checks + "insert if not found"
  -- removed devices (v36 A1, decision 34): the vendor this device last had is gone, so it is not made a new one
  if p_last_vendor_id is not null and not exists (select 1 from cl_vendors where id = p_last_vendor_id) then   -- removed devices
    raise exception 'DEVICE_REMOVED: This device belongs to a business that no longer exists on seiGEN. Reset this device.' using errcode = 'P0001';   -- removed devices
  end if;                                                                                                   -- removed devices
  v_vendor := cl_install_vendor(p_install_id, p_shop_secret_phrase, p_device_key, true, v_business_name, v_device_code);

  update cl_vendors set
    business_name       = coalesce(v_business_name, business_name),
    owner_name          = coalesce(v_owner_name, owner_name),
    phone               = coalesce(v_phone, phone),
    city                = coalesce(v_city, city),
    location            = coalesce(v_location, location),
    device_code         = coalesce(v_device_code, device_code),
    shop_secret_phrase  = coalesce(v_vendor.shop_secret_phrase, p_shop_secret_phrase),
    rpn_id              = coalesce(v_vendor.rpn_id, p_rpn_hint_id),
    last_checkin_at     = now()
  where id = v_vendor.id
  returning * into v_vendor;

  update cl_terminals set last_seen_ts = now(),
         app_build = case when p_app_build > 0 then p_app_build end, app_build_ts = now()   -- build guard
   where vendor_id = v_vendor.id
    returning id, active, branch_id, app_build                       -- shared stock lock: + branch_id, app_build
         into v_terminal_id, v_terminal_active, v_branch_id, v_app_build;   -- Phase 2: + active

  -- shared stock lock: a till at a shared-stock branch on a build before v7 must not sell
  if v_terminal_id is not null then
    v_shared_lock := coalesce((select stock_mode = 'shared' from cl_branches where id = v_branch_id), false)
                     and coalesce(v_app_build, 0) < 7;
  end if;

  -- admin passcode seed: a check value the main branch set for this till, delivered once
  if v_terminal_id is not null then
    update cl_terminal_admin_seeds set delivered_ts = now()
     where terminal_id = v_terminal_id and delivered_ts is null
    returning json_build_object('salt', salt, 'check', check_value, 'rounds', rounds, 'set_ts', created_ts) into v_admin_seed;
  end if;

  select coalesce(json_agg(json_build_object('id', id, 'title', title, 'body', body, 'created_at', created_at)), '[]'::json)
    into v_messages
    from cl_vendor_messages
    where vendor_id = v_vendor.id and channel = 'in_app' and status = 'pending';

  update cl_vendor_messages
    set status = 'delivered', delivered_at = now()
    where vendor_id = v_vendor.id and channel = 'in_app' and status = 'pending';

  return json_build_object(
    'vendor_id', v_vendor.id,
    'status', v_vendor.status,
    'lock_cart', case when v_shared_lock then true else v_vendor.lock_cart end,                 -- shared stock lock
    'lock_add_product', v_vendor.lock_add_product,
    'lock_reason', case when v_shared_lock and not coalesce(v_vendor.lock_cart, false)         -- shared stock lock
                        then 'This branch uses shared stock. Update the app before selling: tap Reload on the update banner, or reopen the app while online.'
                        else v_vendor.lock_reason end,
    'cycle_start_date', v_vendor.cycle_start_date,
    'messages', v_messages,
    'business_id', v_vendor.business_id,        -- Phase 1, additive
    'terminal_id', v_terminal_id,               -- Phase 1, additive
    'terminal_active', v_terminal_active,       -- Phase 2, additive
    'admin_seed', v_admin_seed,                 -- admin passcode seed, additive
    'min_build', v_min_build,                   -- minimum build, additive
    'update_required', coalesce(p_app_build, 0) > 0 and p_app_build < v_min_build   -- minimum build, additive
  );
end;
$function$;

-- same grants as live (PUBLIC, anon, authenticated, service_role)
grant execute on function public.cl_device_checkin(text, text, text, text, text, text, text, text, uuid, text, integer, uuid)
  to public, anon, authenticated, service_role;

-- 6. About page: the company details from Console → Settings (A5) -----------------
insert into public.cl_app_settings (key, value, label, description)
values ('company_website', 'digitalcommerce.com', 'Company website', 'Shown on the About page of Commerce Lite')
on conflict (key) do nothing;

create function public.cl_company_info() returns json
language sql stable security definer set search_path = public as $fn$
  select json_build_object(
    'name',       (select nullif(btrim(value), '') from cl_app_settings where key = 'company_name'),
    'address',    (select nullif(btrim(value), '') from cl_app_settings where key = 'company_address'),
    'website',    (select nullif(btrim(value), '') from cl_app_settings where key = 'company_website'),
    'updated_at', (select max(updated_at) from cl_app_settings where key in ('company_name', 'company_address', 'company_website')));
$fn$;
revoke all on function public.cl_company_info() from public, anon, authenticated;
grant execute on function public.cl_company_info() to anon, authenticated;
revoke all on function public.cl_vendor_removed_device() from public, anon, authenticated;

notify pgrst, 'reload schema';

commit;
